-- Placement slots. Derived from the hand-authored layout: each existing
-- placement becomes a slot, so the current arrangement turns into
-- inventory that can be re-sold rather than being fixed forever.
insert into placement_slots (scene_id, room_id, code, label, category_code,
                             kind, room_type, x_mm, y_mm, z_mm, rotation_deg,
                             max_width_mm, max_depth_mm, is_premium)
select sc.id, r.id, v.code, v.label, v.cat, v.kind::product_kind,
       r.room_type, v.x, v.y, v.z, v.rot, v.maxw, v.maxd, v.premium
from scenes sc
cross join (values
  ('living', 'living-rug-1', 'Living rug position', 'rug', 'object',
   7800.0, 2300.0, 0.0, 0.0, 3450.0, 2530.0, false),
  ('living', 'living-sofa-2', 'Living sofa position', 'sofa', 'object',
   8400.0, 830.0, 0.0, 0.0, 2563.3, 938.4, true),
  ('dining', 'dining-sofa-3', 'Dining sofa position', 'sofa', 'object',
   11150.0, 830.0, 0.0, 0.0, 2116.0, 954.5, true),
  ('living', 'living-storage-4', 'Living storage position', 'storage', 'object',
   5990.0, 2650.0, 0.0, -90.0, 2121.8, 594.5, false),
  ('living', 'living-television-5', 'Living television position', 'television', 'object',
   5860.0, 2650.0, 780.0, -90.0, 1293.8, 80.5, true),
  ('living', 'living-chair-6', 'Living chair position', 'chair', 'object',
   9400.0, 2500.0, 0.0, 90.0, 1130.4, 1044.2, false),
  ('bed2', 'bed2-storage-7', 'Bed2 storage position', 'storage', 'object',
   9440.0, 8497.0, 0.0, 0.0, 2150.5, 575.0, false),
  ('bed2', 'bed2-television-8', 'Bed2 television position', 'television', 'object',
   9440.0, 8601.0, 800.0, 0.0, 1293.8, 80.5, true),
  ('living', 'living-table-9', 'Living table position', 'table', 'object',
   8200.0, 2600.0, 0.0, 0.0, 1380.0, 805.0, false),
  ('master', 'master-bed-10', 'Master bed position', 'bed', 'object',
   3740.0, 2170.0, 0.0, 180.0, 1748.0, 2162.0, false)
) as v(room_code, code, label, cat, kind, x, y, z, rot, maxw, maxd, premium)
left join rooms r on r.scene_id = sc.id and r.code = v.room_code
where sc.slug = '3bed'
on conflict (scene_id, code) do update set
  label = excluded.label,
  x_mm = excluded.x_mm,
  y_mm = excluded.y_mm,
  z_mm = excluded.z_mm,
  rotation_deg = excluded.rotation_deg,
  is_active = true;

-- Retire the placements of any product that is no longer published.
update placements p set status = 'removed'
  from scenes sc, product_variants pv, products pr
 where p.scene_id = sc.id and p.status = 'live'
   and sc.slug = '3bed'
   and pv.id = p.variant_id and pr.id = pv.product_id
   and pr.status <> 'published';

-- Live placements: fill each slot with the product it was authored with.
insert into placements (scene_id, slot_id, variant_id, shop_id, status, note)
select sc.id, sl.id, pv.id, p.shop_id, 'live', v.note
from scenes sc
join (values
  ('living-rug-1', 'bradlows', 'woven-jute-rug', 'Anchors the seating arrangement.'),
  ('living-sofa-2', 'bradlows', 'drake-3-seater', 'Backs onto the south wall, 125mm clear of it, under its window. MOVED 400mm EAST TO OPEN THE FRONT DOOR: at x 7900 its west end was 451mm from the media console, and a 260mm walker needs 520mm to pass, let alone the 300mm of clearance the route is solved at. The solver could not get from the front door into the room, so it took the visitor the long way round the outside of the house and in through the dining slider -- which is what a person watching the tour reported. 636mm was not enough either -- that is 318mm of clearance and the solver works on a grid, so a channel inflated by its 300mm margin left too little for a cell to land in. At x 8300 the channel is 851mm and the clearance 425mm, which clears the widest rung on the ladder. It sits 215mm east of centre under its window; a door you can walk through is worth more.'),
  ('dining-sofa-3', 'bradlows', 'drake-2-seater-console', 'Under the dining window, backing onto the south wall, the same way the three-seater sits under its own. AT x 10700 IT STOOD 90mm OFF THE BACK OF THE RECLINER -- two seats in two rooms either side of the open boundary, reading as one sofa parked behind another. It lost the west wall to the media console; this is where it went.'),
  ('living-storage-4', 'bradlows', 'modern-black-tv-console', 'West wall, and its centre is pinned between two doors. It must sit far enough NORTH that its padded footprint clears the open front-door leaf -- the solver paints the leaf where it comes to rest, 880mm into the room, and console plus leaf sealed the only way in -- and far enough SOUTH to leave the master bedroom door its swing, 397mm at y 2650 against the 260mm a walker needs. The window is 2452..2810; this is the middle of it.'),
  ('living-television-5', 'bradlows', 'sansui-50-fhd-google-tv', 'Stands on the Modern Black console, facing east into the room.'),
  ('living-chair-6', 'bradlows', 'drake-recliner', 'Footrest extends west into the open floor.'),
  ('bed2-storage-7', 'bradlows', 'juliet-tv-stand', 'Foot wall of bedroom 2, facing the bed; 1870mm wide.'),
  ('bed2-television-8', 'bradlows', 'sansui-50-fhd-google-tv', 'Stands on the Juliet''s top plank, facing the bed.'),
  ('living-table-9', 'bradlows', 'oakwood-coffee-table', 'On the rug between the sofa and the recliner. MOVED EAST OFF THE WAY IN: at x 7700 its padded footprint met the console''s and closed the only corridor from the front door to the rest of the house.'),
  ('master-bed-10', 'bears', 'slumberland-maharani-queen', 'Head to the south wall, away from the door''s swing.')
) as v(slot_code, shop, product, note) on true
join placement_slots sl on sl.scene_id = sc.id and sl.code = v.slot_code
join shops sh on sh.slug = v.shop
join products p on p.shop_id = sh.id and p.slug = v.product
join product_variants pv on pv.product_id = p.id and pv.is_default
where sc.slug = '3bed'
  and sl.is_active
  and not exists (
    select 1 from placements x
      join product_variants xv on xv.id = x.variant_id
      join placement_slots xs on xs.id = x.slot_id
     where xv.product_id = p.id and x.status = 'live'
       and x.scene_id = sc.id
       and xs.room_id is not distinct from sl.room_id
  )
  and not exists (
    select 1 from placements x where x.slot_id = sl.id and x.status = 'live'
  );

-- Finish slots: which product dresses which room's floor. This is what
-- makes "who supplied this floor?" answerable for any surface.
insert into placement_slots (scene_id, room_id, code, label, category_code,
                             kind, room_type, material_name)
select sc.id, r.id, 'floor-' || r.code, r.name || ' floor', 'tile',
       'finish'::product_kind, r.room_type, v.material
from scenes sc
join (values
  ('master', 'tile_pyc61001'),
  ('wir', 'carpet'),
  ('bed3', 'tile_pyc61001'),
  ('bed2', 'tile_pyc61001'),
  ('living', 'tile_pyc61001'),
  ('dining', 'tile_pyc61001'),
  ('hall', 'tile_pyc61001'),
  ('bed4', 'tile_pyc61001')
) as v(room_code, material) on true
join rooms r on r.scene_id = sc.id and r.code = v.room_code
where sc.slug = '3bed'
on conflict (scene_id, code) do update set material_name = excluded.material_name;

-- Wall surfaces: one slot per room, plus the exterior.
insert into placement_slots (scene_id, room_id, code, label, category_code,
                             kind, room_type, material_name)
select sc.id, r.id, 'wall-' || r.code, r.name || ' walls', 'paint',
       'finish'::product_kind, r.room_type, 'wall.' || r.code
from scenes sc join rooms r on r.scene_id = sc.id
where sc.slug = '3bed'
on conflict (scene_id, code) do update set material_name = excluded.material_name;

insert into placement_slots (scene_id, code, label, category_code,
                             kind, room_type, material_name)
select sc.id, 'wall-exterior', 'Exterior walls', 'paint',
       'finish'::product_kind, 'outdoor'::room_type, 'wall.exterior'
from scenes sc where sc.slug = '3bed'
on conflict (scene_id, code) do nothing;

-- Fitting slots: surfaces the catalogue dresses that are neither a
-- floor nor a wall. Door hardware, today.
insert into placement_slots (scene_id, room_id, code, label, category_code,
                             kind, room_type, material_name)
select sc.id, r.id, v.code, v.label, v.cat,
       'finish'::product_kind, r.room_type, v.material
from scenes sc
join (values
  ('hall', 'fitting-hall-hinge_black', 'Hinge Black', 'hardware', 'hinge_black')
) as v(room_code, code, label, cat, material) on true
join rooms r on r.scene_id = sc.id and r.code = v.room_code
where sc.slug = '3bed'
on conflict (scene_id, code) do update set material_name = excluded.material_name;

-- Fill finish slots by matching the slot's material to the product
-- that supplies it. Unsold materials leave their slot empty.
insert into placements (scene_id, slot_id, variant_id, shop_id, status, note)
select sl.scene_id, sl.id, v.id, p.shop_id, 'live',
       'Floor finish supplied by ' || sh.name
from placement_slots sl
join scenes sc on sc.id = sl.scene_id
join product_variants v on v.material_name = sl.material_name
join products p on p.id = v.product_id
join shops sh on sh.id = p.shop_id
where sl.kind = 'finish'
  and sl.is_active
  and sl.material_name is not null
  and p.status = 'published'
  and sc.slug = '3bed'
  and not exists (
    select 1 from placements x where x.slot_id = sl.id and x.status = 'live'
  );

