left join rooms r on r.scene_id = sc.id and r.code = v.room_code
join slot_types st on st.code = v.stype
where sc.slug = '3bed'
on conflict (scene_id, code) do update set
  external_id = excluded.external_id, label = excluded.label,
  category_code = excluded.category_code, origin = excluded.origin,
  slot_type_id = excluded.slot_type_id, priority = excluded.priority,
  x_mm = excluded.x_mm, y_mm = excluded.y_mm, z_mm = excluded.z_mm,
  rotation_deg = excluded.rotation_deg,
  max_width_mm = excluded.max_width_mm,
  max_depth_mm = excluded.max_depth_mm,
  max_height_mm = excluded.max_height_mm,
  last_seen_build = excluded.last_seen_build, is_active = true;

-- ADOPT THE AUTHORED SLOT, WITHOUT MOVING THE PRODUCT.
--
-- The 19 live placements sat on DERIVED slots -- invented from the
-- placements themselves -- so every authored slot covering the same
-- position looked free. `suggest_slots` duly offered the master
-- bedroom's bed position while the Slumberland was standing in it.
--
-- The placement's own coordinates are filled in from the derived slot
-- BEFORE it is repointed. A placement inherits its slot's position when
-- it has none of its own (see v_live_placements), so repointing alone
-- would teleport every product to wherever the authored slot happens to
-- be. Copying first means the identity changes and the furniture does
-- not.
with d as (
  select s.id, s.room_id, s.category_code, s.x_mm, s.y_mm, s.z_mm,
         s.rotation_deg,
         row_number() over (partition by s.room_id, s.category_code
                            order by s.code) as rn
    from placement_slots s
   where s.origin = 'derived' and s.is_active
     and exists (select 1 from placements p
                  where p.slot_id = s.id and p.status = 'live')
), a as (
  select s.id, s.room_id, s.category_code,
         row_number() over (partition by s.room_id, s.category_code
                            order by s.priority desc, s.code) as rn
    from placement_slots s
   where s.origin = 'blender' and s.is_active
     and not exists (select 1 from placements p
                      where p.slot_id = s.id and p.status = 'live')
)
update placements p
   set x_mm = coalesce(p.x_mm, d.x_mm),
       y_mm = coalesce(p.y_mm, d.y_mm),
       z_mm = coalesce(p.z_mm, d.z_mm),
       rotation_deg = coalesce(p.rotation_deg, d.rotation_deg),
       slot_id = a.id
  from d join a on a.room_id is not distinct from d.room_id
              and a.category_code is not distinct from d.category_code
              and a.rn = d.rn
 where p.slot_id = d.id and p.status = 'live';

-- A SECOND PASS, IGNORING THE ROOM.
--
-- Some inventory belongs to the HOUSE rather than to a room -- the
-- exterior walls, the hinges fitted to every door. The catalogue still
-- has to place them somewhere, so the hinge is placed in the hall, and
-- the derived slot inherited that room while the authored one has none.
-- Matching on room first and category second means the ordinary case
-- stays exact and the house-wide case still finds its home.
update placements p
   set x_mm = coalesce(p.x_mm, d.x_mm),
       y_mm = coalesce(p.y_mm, d.y_mm),
       z_mm = coalesce(p.z_mm, d.z_mm),
       rotation_deg = coalesce(p.rotation_deg, d.rotation_deg),
       slot_id = a.id
  from placement_slots d, placement_slots a
 where p.slot_id = d.id and p.status = 'live'
   and d.origin = 'derived' and d.is_active
   and a.origin = 'blender' and a.is_active and a.room_id is null
   and a.category_code is not distinct from d.category_code
   and a.scene_id = d.scene_id
   and not exists (select 1 from placements x
                    where x.slot_id = a.id and x.status = 'live');

-- Retire a derived slot only when it is EMPTY and an authored slot now
-- covers the same room and category. A derived slot holding a live
-- placement is left exactly as it is: it says where a product actually
-- stands, and deactivating it would take that product out of the house.
update placement_slots d set is_active = false
 where d.origin = 'derived' and d.is_active
   and not exists (select 1 from placements p
                    where p.slot_id = d.id and p.status = 'live')
   and exists (select 1 from placement_slots a
                where a.scene_id = d.scene_id and a.origin = 'blender'
                  and (a.room_id is not distinct from d.room_id
                       or a.room_id is null)
                  and a.category_code is not distinct from d.category_code);

-- The catalogue authors where a product stands; this mirrors it.
-- Deliberately NOT a coalesce: the catalogue is the source, so a
-- placement that moved there moves here. Anything placed by an
-- operator in the admin screen has no row in this list and is left
-- entirely alone.
update placements p
   set x_mm = v.x, y_mm = v.y, z_mm = v.z, rotation_deg = v.rot
  from scenes sc, product_variants pv, products pr, shops sh, (values
  ('bradlows', 'woven-jute-rug', 7800.0, 2300.0, 0.0, 0.0, 'living', false),
  ('bradlows', 'drake-3-seater', 8400.0, 830.0, 0.0, 0.0, 'living', false),
  ('bradlows', 'drake-2-seater-console', 11150.0, 830.0, 0.0, 0.0, 'dining', false),
  ('bradlows', 'modern-black-tv-console', 5990.0, 2650.0, 0.0, -90.0, 'living', false),
  ('bradlows', 'sansui-50-fhd-google-tv', 5860.0, 2650.0, 780.0, -90.0, 'living', true),
  ('bradlows', 'drake-recliner', 9400.0, 2500.0, 0.0, 90.0, 'living', false),
  ('bradlows', 'juliet-tv-stand', 9440.0, 8497.0, 0.0, 0.0, 'bed2', false),
  ('bradlows', 'sansui-50-fhd-google-tv', 9440.0, 8601.0, 800.0, 0.0, 'bed2', true),
  ('bradlows', 'oakwood-coffee-table', 8200.0, 2600.0, 0.0, 0.0, 'living', false),
  ('bears', 'slumberland-maharani-queen', 3740.0, 2170.0, 0.0, 180.0, 'master', false)
) as v(shop, product, x, y, z, rot, room, by_room)
 where p.scene_id = sc.id and p.status = 'live'
   and sc.slug = '3bed'
   and pv.id = p.variant_id and pr.id = pv.product_id
   and sh.id = pr.shop_id
   and sh.slug = v.shop and pr.slug = v.product
   and (not v.by_room or exists (
     select 1 from placement_slots psl
       join rooms prm on prm.id = psl.room_id
      where psl.id = p.slot_id and prm.code = v.room))
   and (p.x_mm is distinct from v.x or p.y_mm is distinct from v.y
        or p.z_mm is distinct from v.z
        or p.rotation_deg is distinct from v.rot);

-- Re-point a placement whose product has moved to another room.
update placements p
   set slot_id = t.id
  from scenes sc, product_variants pv, products pr, shops sh,
       placement_slots t, rooms rm, (values
  ('bradlows', 'woven-jute-rug', 'living'),
  ('bradlows', 'drake-3-seater', 'living'),
  ('bradlows', 'drake-2-seater-console', 'dining'),
  ('bradlows', 'modern-black-tv-console', 'living'),
  ('bradlows', 'drake-recliner', 'living'),
  ('bradlows', 'juliet-tv-stand', 'bed2'),
  ('bradlows', 'oakwood-coffee-table', 'living'),
  ('bears', 'slumberland-maharani-queen', 'master')
) as v(shop, product, room)
 where p.scene_id = sc.id and p.status = 'live'
   and sc.slug = '3bed'
   and pv.id = p.variant_id and pr.id = pv.product_id
   and sh.id = pr.shop_id
   and sh.slug = v.shop and pr.slug = v.product
   and rm.scene_id = sc.id and rm.code = v.room
   and t.scene_id = sc.id and t.room_id = rm.id and t.is_active
   and t.category_code = pr.category_code
   -- only when the slot it has is in the wrong room
   and not exists (select 1 from placement_slots cur
                    where cur.id = p.slot_id and cur.room_id = rm.id)
   -- and never onto a position something else is standing in
   and not exists (select 1 from placements o
                    where o.slot_id = t.id and o.status = 'live'
                      and o.id <> p.id);

-- RETIRE A PLACEMENT THE CATALOGUE NO LONGER AUTHORS.
--
-- Moving a product from one room to another left the old placement
-- standing. The insert fills the new room's slot -- correctly, they
-- are different rooms -- and the re-point only drags the old row over
-- when the new room has a free authored slot of the same category.
-- When it has none, nothing removes it, and the house advertises two
-- of a sofa it owns one of. The two-seater was live in the living room
-- and the dining room at the same time, at the same coordinates.
--
-- ONLY PRODUCTS THIS CATALOGUE PLACES ARE TOUCHED. Anything it knows
-- nothing about was put there by an operator in the admin screen and is
-- theirs to move. House-wide inventory -- the door hinges -- sits on
-- slots with no room at all, and the join to `rooms` skips it.
update placements p set status = 'removed'
  from scenes sc, product_variants pv, products pr, shops sh,
       placement_slots psl, rooms prm
 where p.scene_id = sc.id and p.status = 'live'
   and sc.slug = '3bed'
   and pv.id = p.variant_id and pr.id = pv.product_id
   and sh.id = pr.shop_id
   and psl.id = p.slot_id and prm.id = psl.room_id
   and (sh.slug, pr.slug) in (
  ('bears', 'slumberland-maharani-queen'),
  ('bradlows', 'drake-2-seater-console'),
  ('bradlows', 'drake-3-seater'),
  ('bradlows', 'drake-recliner'),
  ('bradlows', 'juliet-tv-stand'),
  ('bradlows', 'modern-black-tv-console'),
  ('bradlows', 'oakwood-coffee-table'),
  ('bradlows', 'sansui-50-fhd-google-tv'),
  ('bradlows', 'woven-jute-rug')
   )
   and (sh.slug, pr.slug, prm.code) not in (
  ('bears', 'slumberland-maharani-queen', 'master'),
  ('bradlows', 'drake-2-seater-console', 'dining'),
  ('bradlows', 'drake-3-seater', 'living'),
  ('bradlows', 'drake-recliner', 'living'),
  ('bradlows', 'juliet-tv-stand', 'bed2'),
  ('bradlows', 'modern-black-tv-console', 'living'),
  ('bradlows', 'oakwood-coffee-table', 'living'),
  ('bradlows', 'sansui-50-fhd-google-tv', 'bed2'),
  ('bradlows', 'sansui-50-fhd-google-tv', 'living'),
  ('bradlows', 'woven-jute-rug', 'living')
   );

commit;
